              * If the index is the same, then this qp shouldn't be retired
              */
-            if (count & (QP_OBTAINED|QP_RETIRED))
+            if ((count & (QP_OBTAINED|QP_RETIRED)) != 0 &&
+                (ATOMIC_ADD_FETCH(&lock->qp_group[qp_idx].users, (uint64_t)0,
+                                  __ATOMIC_RELAXED) & QP_RETIRED) != 0)
                 fprintf(stderr, "qp %d with count %lx should have been followed with index update\n", qp_idx, count);
+            else /* the qp_idx is no longer retired, so everything is ok */
+                expect_idx_update = 0;
